    c.style.width = cssW + "px";
    const g = c.getContext("2d");
    const img = g.createImageData(this.w, this.h), d = img.data, px = this.px;
    for (let i = 0; i < px.length; i += 4) {
      const a = px[i + 3];
      if (a <= 0) continue;
      d[i] = px[i] / a; d[i + 1] = px[i + 1] / a; d[i + 2] = px[i + 2] / a; d[i + 3] = a * 255;
    }
