    if (PLACES.indexOf(kind) >= 0) return (it) => truth(place(it, kind));
    if (GROUP_WORDS.has(kind)) return (it) => truth(inGroup(it, kind));
    if (STAT_WORDS[kind] !== undefined) { const s = STAT_WORDS[kind]; return (it) => itemStat(it, s, 0, op, a, b); }
