  /* a picker's order: the page's kind order, then the type, the tier, the quality level */
  const baseOrder = (order) => (x, y) => kindRank(x.kind, order) - kindRank(y.kind, order) ||
    baseType(x.b).localeCompare(baseType(y.b)) || (TIER_RANK[tierOf(x.b)] || 0) - (TIER_RANK[tierOf(y.b)] || 0) ||
    x.b.qlvl - y.b.qlvl;
